from itertools import product
from .errors import CloseError

CONTROL_FIELDS = ('gross_cents', 'refund_cents')


def allocate(captures, refunds, fixed, controls, merchants):
    for merchant, row in controls.items():
        if merchant not in merchants:
            raise CloseError('Signed control for undeclared merchant: ' + str(merchant))
        if not row or set(row) - set(CONTROL_FIELDS):
            raise CloseError('Unsupported signed control fields for merchant ' + str(merchant))
    identities = sorted(captures)
    choices = []
    for identity in identities:
        if identity in fixed:
            if fixed[identity] not in merchants:
                raise CloseError('Posted merchant is not declared: ' + identity)
            choices.append([fixed[identity]])
        else:
            options = sorted(m for m in set(captures[identity]['eligible']) if m in merchants)
            if not options:
                raise CloseError('Capture has no declared eligible merchant: ' + identity)
            choices.append(options)
    for combination in product(*choices):
        totals = {m: {'gross_cents': 0, 'refund_cents': 0} for m in merchants}
        for identity, merchant in zip(identities, combination):
            totals[merchant]['gross_cents'] += captures[identity]['amount_cents']
            totals[merchant]['refund_cents'] += refunds.get(identity, 0)
        if all(totals[m][name] == amount for m, row in controls.items() for name, amount in row.items()):
            return dict(zip(identities, combination))
    raise CloseError('No permitted allocation matches the signed merchant controls')

import json
import os
import tempfile
from pathlib import Path
from .errors import CloseError
from .ledger import current_position
from .allocation import allocate

AMOUNT_FIELDS = ('gross_cents', 'refund_cents', 'net_cents')


def build_close(batch):
    captures, refunds, fixed = current_position(batch)
    gross = sum(row['amount_cents'] for row in captures.values())
    refunded = sum(refunds.values())
    totals = {'gross_cents': gross, 'refund_cents': refunded, 'net_cents': gross-refunded}
    if totals != batch['bank']:
        raise CloseError('Processor position does not match the bank settlement')
    period = batch['period']
    assignment = allocate(captures, refunds, fixed, batch['controls'], period['merchants'])
    merchants = {m: dict(gross_cents=0, refund_cents=0, net_cents=0, capture_count=0) for m in period['merchants']}
    lines = []
    for identity, merchant in sorted(assignment.items()):
        amount = captures[identity]['amount_cents']; refunded = refunds.get(identity, 0)
        row = dict(capture=identity, merchant=merchant, gross_cents=amount, refund_cents=refunded, net_cents=amount-refunded)
        lines.append(row)
        for key in AMOUNT_FIELDS:
            merchants[merchant][key] += row[key]
        merchants[merchant]['capture_count'] += 1
    return dict(batch=period['batch'], currency=period['currency'], as_of=period['as_of'], totals=totals, merchants=merchants, allocations=lines)


def validate_close(package, batch):
    """Check a close package against the records independently of how it was built."""
    captures, refunds, fixed = current_position(batch)
    period = batch['period']
    for key in ('batch', 'currency', 'as_of'):
        if package.get(key) != period[key]:
            raise CloseError('Close %s does not match the period' % key)
    lines = package.get('allocations')
    if not isinstance(lines, list) or len(lines) != len(captures):
        raise CloseError('Close must have exactly one allocation per current capture')
    expected = {m: dict(gross_cents=0, refund_cents=0, net_cents=0, capture_count=0) for m in period['merchants']}
    seen = set()
    for line in lines:
        capture, merchant = line.get('capture'), line.get('merchant')
        if capture not in captures or capture in seen:
            raise CloseError('Close allocation is unknown or duplicated: %s' % (capture,))
        seen.add(capture)
        if merchant not in expected or merchant not in captures[capture]['eligible']:
            raise CloseError('Close allocates %s to an ineligible merchant' % capture)
        if capture in fixed and fixed[capture] != merchant:
            raise CloseError('Close moves posted capture ' + capture)
        gross, refunded = captures[capture]['amount_cents'], refunds.get(capture, 0)
        if [line.get(k) for k in AMOUNT_FIELDS] != [gross, refunded, gross-refunded]:
            raise CloseError('Close allocation amounts differ from records: ' + capture)
        for key in AMOUNT_FIELDS:
            expected[merchant][key] += line[key]
        expected[merchant]['capture_count'] += 1
    merchants = package.get('merchants')
    if not isinstance(merchants, dict) or set(merchants) != set(expected):
        raise CloseError('Close merchants differ from the declared merchants')
    for merchant, row in expected.items():
        if any(merchants[merchant].get(k) != v for k, v in row.items()):
            raise CloseError('Close merchant totals differ from supporting lines: ' + merchant)
    for merchant, row in batch['controls'].items():
        if any(expected[merchant][k] != v for k, v in row.items()):
            raise CloseError('Close does not match signed control for merchant ' + merchant)
    totals = {k: sum(row[k] for row in expected.values()) for k in AMOUNT_FIELDS}
    if totals != batch['bank'] or package.get('totals') != totals:
        raise CloseError('Close totals do not match the bank settlement')
    return package


def write_close(batch, output):
    package = validate_close(build_close(batch), batch)
    path = Path(output); path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(dir=path.parent, prefix='.close-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w') as stream:
            json.dump(package, stream, indent=2); stream.write('\n'); stream.flush(); os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary): os.unlink(temporary)
    return package

