# Delivery metadata: identifies an envelope, not the monetary record it carries.
DELIVERY_FIELDS = ('event_id', 'known')
KINDS = ('capture', 'refund')


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _check_delivery(row):
    if row.get('kind') not in KINDS:
        raise CloseError('Unknown processor record kind: %r' % (row.get('kind'),))
    if not isinstance(row.get('id'), str) or not row['id']:
        raise CloseError('Processor record has no entity ID')
    if not _is_int(row.get('revision')) or row['revision'] < 1:
        raise CloseError('Processor revision must be a positive integer: %s' % row['id'])
    if not _is_int(row.get('known')):
        raise CloseError('Processor known time must be an integer: %s' % row['id'])
    if not isinstance(row.get('final'), bool):
        raise CloseError('Processor final flag must be boolean: %s' % row['id'])
    if not _is_int(row.get('amount_cents')) or row['amount_cents'] < 0:
        raise CloseError('Processor amount must be nonnegative integer cents: %s' % row['id'])


def current_events(deliveries, as_of):
    """Select, for each (kind, id), the highest final revision known at the cutoff.

    Selection is independent of delivery order. Exact redeliveries collapse into
    one record; differing payloads for one visible (kind, id, revision) are
    rejected whether or not that revision would be selected.
    """
    revisions = {}
    for row in deliveries:
        _check_delivery(row)
        if row['known'] > as_of:
            continue
        identity = (row['kind'], row['id'], row['revision'])
        value = {k: v for k, v in row.items() if k not in DELIVERY_FIELDS}
        if identity in revisions and revisions[identity] != value:
            raise CloseError('Conflicting processor revision: %s %s revision %d' % identity)
        revisions.setdefault(identity, value)
    current = {}
    for (kind, entity, revision), value in revisions.items():
        if not value['final']:
            continue
        key = (kind, entity)
        if key not in current or current[key]['revision'] < revision:
            current[key] = value
    return current
